//! Guards against the hand-written minimal ABI in `src/abi.rs` drifting from the contracts' merged ABI
//! (`contracts/abi/PerpExchange.merged.json`, regenerated by the contracts project). Refresh procedure: see README
//! ("Refreshing the ABI"). The test reads the JSON at test time, so it always checks the CURRENT merged ABI.
use alloy::{json_abi::JsonAbi, sol_types::{SolCall, SolError, SolEvent}};
use perp_keeper::{abi::IPerp, chain::{MARKET_FUNDING_INTERVAL_WORD, MARKET_LOT_WORD}};

fn merged() -> Option<JsonAbi> {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../contracts/abi/PerpExchange.merged.json");
    let txt = std::fs::read_to_string(&p).ok()?;
    let v: serde_json::Value = serde_json::from_str(&txt).ok()?;
    let abi = if v.is_array() { v } else { v.get("abi")?.clone() };
    serde_json::from_value(abi).ok()
}

fn require() -> JsonAbi {
    match merged() {
        Some(a) => a,
        None if std::env::var("KEEPER_ABI_OPTIONAL").is_ok() => { eprintln!("merged ABI not found; skipped"); std::process::exit(0) }
        None => panic!("contracts/abi/PerpExchange.merged.json not found or unreadable (set KEEPER_ABI_OPTIONAL=1 to skip)"),
    }
}

macro_rules! fn_sigs { ($abi:expr, $($c:ty),* $(,)?) => { $( {
    let sig = <$c as SolCall>::SIGNATURE;
    let found = $abi.functions().any(|f| f.signature() == sig);
    assert!(found, "function `{sig}` used by the keeper is missing from the merged ABI (contracts changed? refresh src/abi.rs)");
} )* } }
macro_rules! ev_sigs { ($abi:expr, $($c:ty),* $(,)?) => { $( {
    let sig = <$c as SolEvent>::SIGNATURE;
    let found = $abi.events().any(|f| f.signature() == sig);
    assert!(found, "event `{sig}` used by the keeper is missing/changed in the merged ABI");
} )* } }
macro_rules! err_sigs { ($abi:expr, $($c:ty),* $(,)?) => { $( {
    let sig = <$c as SolError>::SIGNATURE;
    let found = $abi.errors().any(|f| f.signature() == sig);
    assert!(found, "error `{sig}` used by the keeper is missing/changed in the merged ABI");
} )* } }

#[test]
fn every_function_event_and_error_the_keeper_uses_exists_in_the_merged_abi() {
    let abi = require();
    fn_sigs!(abi,
        IPerp::marketCountCall, IPerp::markPriceCall, IPerp::BACKSTOPCall, IPerp::accountStateCall, IPerp::isoStateCall,
        IPerp::positionsCall, IPerp::condsCall, IPerp::twapStatusCall, IPerp::adlDebtCall, IPerp::adlScoreCall,
        IPerp::liqFeeBpsCall, IPerp::keeperShareBpsCall, IPerp::closeFactorBpsCall, IPerp::fullCloseNotionalCall,
        IPerp::getMarketCall, IPerp::pokeFundingCall, IPerp::liquidateCall, IPerp::executeConditionalCall,
        IPerp::executeTwapSliceCall, IPerp::adlCall, IPerp::writeOffCall,
        IPerp::syncBackstopCall, IPerp::adlHealthCall, IPerp::backstopEquityCall, IPerp::bsInsDrawnCall, IPerp::bsDebtCall, IPerp::unresolvedBadDebtCall);
    ev_sigs!(abi, IPerp::Deposit, IPerp::Fill, IPerp::CondPlaced, IPerp::CondTriggered, IPerp::CondCanceled,
        IPerp::TwapPlaced, IPerp::TwapDone, IPerp::TwapCanceled, IPerp::Liquidated, IPerp::BadDebtUnresolved, IPerp::BackstopSynced, IPerp::AdlSkipped);
    err_sigs!(abi, IPerp::NotAuthorized, IPerp::BadParam, IPerp::MarketRestricted, IPerp::OracleDegraded, IPerp::Unhealthy,
        IPerp::NotLiquidatable, IPerp::Expired, IPerp::TooManyOrders, IPerp::ReentrancyGuardReentrantCall, IPerp::WithdrawGated);
}

#[test]
fn return_types_the_keeper_decodes_still_match() {
    let abi = require();
    let outs = |name: &str| -> Vec<String> {
        abi.function(name).unwrap_or_else(|| panic!("{name} missing"))[0].outputs.iter().map(|p| p.ty.clone()).collect()
    };
    assert_eq!(outs("liqFeeBps"), vec!["uint32"]);
    assert_eq!(outs("keeperShareBps"), vec!["uint32"]);
    assert_eq!(outs("closeFactorBps"), vec!["uint32"]);
    assert_eq!(outs("fullCloseNotional"), vec!["uint64"]);
    assert_eq!(outs("positions"), vec!["int256", "int256", "int256", "bool", "int256", "uint256"]);
    assert_eq!(outs("accountState"), vec!["int256", "uint256", "uint256", "uint256", "uint256"]);
    assert_eq!(outs("isoState"), vec!["bool", "int256", "int256", "uint256", "uint256", "uint256"]);
}

/// `chain::parse_market_info` reads `lot` and `fundingInterval` by word index of the `getMarket` tuple.
#[test]
fn get_market_tuple_layout_matches_the_hardcoded_word_indexes() {
    let abi = require();
    let f = &abi.function("getMarket").expect("getMarket")[0];
    let comps = &f.outputs[0].components;
    assert_eq!(comps[MARKET_LOT_WORD].name, "lot", "Market struct changed: update MARKET_LOT_WORD in chain.rs");
    assert_eq!(comps[MARKET_FUNDING_INTERVAL_WORD].name, "fundingInterval", "Market struct changed: update MARKET_FUNDING_INTERVAL_WORD");
    // the words before must all be single static words, otherwise index != word offset
    for c in &comps[..=MARKET_FUNDING_INTERVAL_WORD] {
        assert!(!c.ty.starts_with("tuple") && !c.ty.contains('[') && c.ty != "bytes" && c.ty != "string", "non-static field {} before fundingInterval", c.name);
    }
}
